    $rows=@('<row r="1" ht="48" customHeight="1">'+(C B1 'SAMI Meeting Pack' 3)+'</row>');$pairs=@(@('Classification',$m.classification),@('Generated (Adelaide)',$m.time),@('Scope',$m.scope),@('Revision',$m.revision.Substring(0,12)),@('Prepared from','SAMI Kanban'),@('Exported projects',$projects.Count));$r=3;foreach($p in $pairs){$rows+='<row r="'+$r+'">'+(C ('A'+$r) $p[0] 2)+(C ('B'+$r) $p[1])+'</row>';$r++};if($m.classification-eq'Preview'){$rows+='<row r="10">'+(C A10 'PREVIEW - NOT AUTHORISED' 1)+'</row>'};Add-MeetingPackZipText $z 'xl/worksheets/sheet1.xml' ('<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><cols><col min="1" max="1" width="24" customWidth="1"/><col min="2" max="3" width="35" customWidth="1"/></cols><sheetData>'+($rows-join'')+'</sheetData><mergeCells count="1"><mergeCell ref="B1:C1"/></mergeCells><drawing r:id="rId1"/></worksheet>');Add-MeetingPackZipText $z 'xl/worksheets/_rels/sheet1.xml.rels' '<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/></Relationships>';$logoPath=Join-Path $PSScriptRoot 'assets\icons\sami_project_portfolio-192.png';if(Test-Path -LiteralPath $logoPath){Add-MeetingPackZipBytes $z 'xl/media/sami-mark.png' ([IO.File]::ReadAllBytes($logoPath));Add-MeetingPackZipText $z 'xl/drawings/drawing1.xml' '<?xml version="1.0"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:oneCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>250000</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>80000</xdr:rowOff></xdr:from><xdr:ext cx="520000" cy="520000"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="1" name="Circular SAMI mark