    $rows=New-Object Collections.Generic.List[string]
    $rows.Add('<row r="1" ht="52" customHeight="1">'+(XCell 'B1' 'SAMI Meeting Pack' 3)+'</row>')
    $subtitle=$m.classification+' | Generated '+$m.time+' | Revision '+$m.revision.Substring(0,12)+' | Prepared from: SAMI Kanban'
    $rows.Add('<row r="2" ht="28" customHeight="1">'+(XCell 'A2' $subtitle 4)+'</row>')
    $rows.Add('<row r="3" ht="26" customHeight="1">'+(XCell 'A3' 'Project Name' 1)+(XCell 'B3' 'Next Action' 1)+(XCell 'C3' 'Status' 1)+(XCell 'D3' 'Project Lead' 1)+(XCell 'E3' 'Latest Update' 1)+'</row>')
    $r=4;foreach($project in $projects){$rows.Add('<row r="'+$r+'" ht="48" customHeight="1">'+(XCell ('A'+$r) $project.name 2)+(XCell ('B'+$r) $project.nextAction 4)+(XCell ('C'+$r) $project.status)+(XCell ('D'+$r) $project.lead)+(XCell ('E'+$r) $project.update)+'</row>');$r++}
    $last=[Math]::Max(3,$r-1)
    $sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"><pane xSplit="2" ySplit="3" topLeftCell="C4" activePane="bottomRight" state="frozen"/><selection pane="bottomRight" activeCell="C4" sqref="C4"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols><col min="1" max="1" width="32" customWidth="1"/><col min="2" max="2" width="52" customWidth="1"/><col min="3" max="3" width="18" customWidth="1"/><col min="4" max="4" width="24" customWidth="1"/><col min="5" max="5" width="58" customWidth="1"/></cols><sheetData>'+($rows-join'')+'</sheetData><mergeCells count="2"><mergeCell ref="B1:E1"/><mergeCell ref="A2:E2"/></mergeCells><drawing r:id="rId1"/><tableParts count="1"><tablePart r:id="rId2"/></tableParts></worksheet>'
    Add-MeetingPackZipText $z 'xl/worksheets/sheet1.xml' $sheet
    Add-MeetingPackZipText $z 'xl/worksheets/_rels/sheet1.xml.rels' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/table" Target="../tables/table1.xml"/></Relationships>'
    Add-MeetingPackZipText $z 'xl/tables/table1.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><table xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" id="1" name="ProjectsTable" displayName="ProjectsTable" ref="A3:E'+$last+'" totalsRowShown="0"><autoFilter ref="A3:E'+$last+'"/><tableColumns count="5"><tableColumn id="1" name="Project Name"/><tableColumn id="2" name="Next Action"/><tableColumn id="3" name="Status"/><tableColumn id="4" name="Project Lead"/><tableColumn id="5" name="Latest Update"/></tableColumns><tableStyleInfo name="TableStyleMedium2" showFirstColumn="0" showLastColumn="0" showRowStripes="1" showColumnStripes="0"/></table>')
    $logo=Join-Path $PSScriptRoot 'assets\icons\sami_project_portfolio-192.png';if(-not(Test-Path -LiteralPath $logo)){throw 'SAMI workbook branding icon is unavailable.'};Add-MeetingPackZipBytes $z 'xl/media/sami-mark.png' ([IO.File]::ReadAllBytes($logo))
    Add-MeetingPackZipText $z 'xl/drawings/drawing1.xml' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:oneCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>180000</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>90000</xdr:rowOff></xdr:from><xdr:ext cx="500000" cy="500000"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="1" name="Circular SAMI mark"/><xdr:cNvPicPr preferRelativeResize="0"/></xdr:nvPicPr><xdr:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="500000" cy="500000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor></xdr:wsDr>'
    Add-MeetingPackZipText $z 'xl/drawings/_rels/drawing1.xml.rels' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/sami-mark.png"/></Relationships>'
    Add-MeetingPackZipText $z 'docProps/custom.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><property fmtid="{D5CDD505-2E9C-101B-9397-08002B2CF9AE}" pid="2" name="BoardRevision"><vt:lpwstr>'+$m.revision+'</vt:lpwstr></property></Properties>')
  } finally {$z.Dispose()}
  return $ms.ToArray()
}